22	function formatEventTime(startAt: string, endAt: string): string {
23	  const start = new Date(startAt);
24	  const end = new Date(endAt);
25	  const dateStr = start.toLocaleDateString('en-US', {
26	    weekday: 'short',
27	    month: 'short',
28	    day: 'numeric',
29	  });
30	  const startTime = start.toLocaleTimeString('en-US', {
31	    hour: 'numeric',
32	    minute: '2-digit',
33	    hour12: true,
34	  });
35	  const endTime = end.toLocaleTimeString('en-US', {
36	    hour: 'numeric',
37	    minute: '2-digit',
38	    hour12: true,
39	  });
40	  return `${dateStr} · ${startTime} – ${endTime}`;
41	}
42	
43	function statusLabel(status: string): string {
44	  switch (status) {
45	    case 'auto_approved':
46	    case 'approved':
47	      return 'On standby';
48	    case 'pending_review':
49	      return 'Pending approval';
50	    case 'rejected':
51	      return 'Rejected';
52	    default:
53	      return status;
54	  }
55	}
