57	export function StudentStandbyPanel({
58	  open,
59	  onClose,
60	  locationId,
61	  studentId,
62	}: StudentStandbyPanelProps) {
63	  const [opportunities, setOpportunities] = useState<Record<string, unknown>[]>(
64	    [],
65	  );
66	  const [activeEntries, setActiveEntries] = useState<StandbyEntry[]>([]);
67	  const [joiningEventId, setJoiningEventId] = useState<string | null>(null);
68	  const [leavingEntryId, setLeavingEntryId] = useState<string | null>(null);
69	  const [loading, setLoading] = useState(true);
70	  const [confirmAvailability, setConfirmAvailability] = useState<string | null>(
71	    null,
72	  );
73	
74	  const load = useCallback(async () => {
75	    if (!locationId || !studentId) return;
76	    try {
77	      const [opps, entries] = await Promise.all([
78	        fetchStandbyOpportunities(locationId, studentId, 7),
79	        fetchStudentStandby(locationId, studentId),
80	      ]);
81	      // Filter out opportunities the student is already on standby for
82	      const activeEventIds = new Set(entries.map((e) => e.scheduleEventId));
83	      setOpportunities(opps.filter((o) => !activeEventIds.has(o.id as string)));
84	      setActiveEntries(entries.filter((e) => e.approvalStatus !== 'rejected'));
85	    } catch {
86	      // Silently ignore load errors — the panel is non-critical
87	    } finally {
88	      setLoading(false);
89	    }
90	  }, [locationId, studentId]);
91	
92	  useEffect(() => {
93	    void load();
94	  }, [load]);
95	
96	  async function handleJoin(eventId: string) {
97	    setConfirmAvailability(eventId);
98	  }
99	
100	  async function handleConfirmJoin(eventId: string) {
101	    setJoiningEventId(eventId);
102	    setConfirmAvailability(null);
103	    try {
104	      await joinStandby(locationId, eventId, {
105	        studentId,
106	        initiatedBy: 'student',
107	        availabilityConfirmed: true,
108	      });
109	      toast.success(
110	        "You've been added to the standby queue. We'll notify you if this slot opens up.",
111	      );
112	      void load();
113	    } catch (err: unknown) {
114	      const msg = err instanceof Error ? err.message : 'Failed to join standby';
115	      toast.error(msg);
116	    } finally {
117	      setJoiningEventId(null);
118	    }
119	  }
120	
121	  async function handleLeave(entryId: string) {
122	    setLeavingEntryId(entryId);
123	    try {
124	      await leaveStandby(locationId, entryId);
125	      toast.success("You've been removed from the standby queue.");
126	      void load();
127	    } catch (err: unknown) {
128	      const msg =
129	        err instanceof Error ? err.message : 'Failed to leave standby';
130	      toast.error(msg);
131	    } finally {
132	      setLeavingEntryId(null);
133	    }
134	  }
135	
136	  return (
137	    <SlideOutDrawer
138	      open={open}
139	      onClose={onClose}
140	      title="Standby Opportunities"
141	      subtitle="Join the standby queue for upcoming flights in the next 7 days."
142	      icon={<ListTodo className="w-3.5 h-3.5 text-white" />}
143	      iconClassName="bg-gradient-to-br from-teal-600 to-cyan-600"
144	      width="md"
145	    >
146	      {loading ? (
147	        <div className="py-4 text-sm text-muted-foreground">
148	          Loading standby opportunities…
149	        </div>
150	      ) : (
151	        <div className="space-y-4 p-1">
152	          {/* Active standby entries */}
153	          {activeEntries.length > 0 && (
154	            <div>
155	              <h4 className="mb-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
156	                Your Active Standby
157	              </h4>
158	              <div className="space-y-2">
159	                {activeEntries.map((entry) => {
160	                  const isLeaving = leavingEntryId === entry.id;
161	                  return (
162	                    <div
163	                      key={entry.id}
164	                      className="flex items-center justify-between rounded-md border border-dashed bg-muted/30 px-3 py-2 text-sm"
165	                    >
166	                      <div className="space-y-0.5">
167	                        <p className="font-medium text-muted-foreground">
168	                          Standby — {statusLabel(entry.approvalStatus)}
169	                        </p>
170	                        <p className="text-xs text-muted-foreground">
171	                          Event: {entry.scheduleEventId.slice(0, 8)}…
172	                        </p>
173	                      </div>
174	                      <button
175	                        type="button"
176	                        onClick={() => void handleLeave(entry.id)}
177	                        disabled={isLeaving}
178	                        className="text-xs text-destructive hover:underline disabled:opacity-50"
179	                      >
180	                        {isLeaving ? 'Removing…' : 'Remove'}
181	                      </button>
182	                    </div>
183	                  );
184	                })}
185	              </div>
186	            </div>
187	          )}
188	
189	          {/* Availability confirmation modal */}
190	          {confirmAvailability && (
191	            <div className="rounded-md border bg-background p-4 shadow-sm">
192	              <p className="mb-3 text-sm font-medium">
193	                Can you make it on time if this slot opens up?
194	              </p>
195	              <p className="mb-4 text-xs text-muted-foreground">
196	                By confirming, you agree to respond promptly to standby
197	                notifications and arrive within the allotted window.
198	              </p>
199	              <div className="flex gap-2">
200	                <button
201	                  type="button"
202	                  onClick={() => void handleConfirmJoin(confirmAvailability)}
203	                  className="rounded-md bg-primary px-3 py-1.5 text-xs font-medium text-primary-foreground"
204	                >
205	                  Yes, add me to standby
206	                </button>
207	                <button
208	                  type="button"
209	                  onClick={() => setConfirmAvailability(null)}
210	                  className="rounded-md border px-3 py-1.5 text-xs font-medium"
211	                >
212	                  Cancel
213	                </button>
214	              </div>
215	            </div>
216	          )}
217	
218	          {/* Opportunities list */}
219	          <div>
220	            <h4 className="mb-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
221	              Standby Opportunities — Next 7 Days
222	            </h4>
223	            {opportunities.length === 0 ? (
224	              <p className="text-sm text-muted-foreground">
225	                No standby opportunities available right now. Check back later.
226	              </p>
227	            ) : (
228	              <div className="space-y-2">
229	                {opportunities.map((event) => {
230	                  const eventId = event.id as string;
231	                  const isJoining = joiningEventId === eventId;
232	                  const isPending = confirmAvailability === eventId;
233	                  return (
234	                    <div
235	                      key={eventId}
236	                      className="flex items-center justify-between rounded-md border bg-background px-3 py-2 text-sm"
237	                    >
238	                      <div className="space-y-0.5">
239	                        <p className="font-medium">
240	                          {(event.title as string) || 'Flight Event'}
